                .lines()
                .map(|line| serde_json::from_str(line).unwrap())
                .collect()
        }
        fn subscriber(&self, filter: &str) -> tracing::Dispatch {
            let buffer = self.clone();
            tracing::Dispatch::new(
                tracing_subscriber::fmt()
                    .json()
                    .without_time()
                    .with_env_filter(
                        EnvFilter::builder()
                            .with_regex(false)
                            .parse(filter)
                            .unwrap(),
                    )
                    .with_writer(move || buffer.clone())
                    .finish(),
            )
        }
    }

    async fn request(
        router: Router,
        method: Method,
        uri: &str,
        filter: &str,
    ) -> (Response, Vec<Value>) {
        let buffer = Buffer::default();
        let request = Request::builder()
            .method(method)
            .uri(uri)
            .header("authorization", "PRIVATE_AUTH_HEADER")
            .body(Body::from("PRIVATE_REQUEST_BODY"))
            .unwrap();
        let response = router
            .oneshot(request)
            .with_subscriber(buffer.subscriber(filter))
            .await
            .unwrap();
        let events = buffer.events();
        let output = serde_json::to_string(&events).unwrap();
        for secret in [
            "PRIVATE_AUTH_HEADER",
            "PRIVATE_REQUEST_BODY",
            "PRIVATE_QUERY",
        ] {
            assert!(!output.contains(secret), "leaked {secret}: {output}");
        }
        (response, events)
    }

